import {STAGES,ITEMS,PRODUCTS,NEEDS,FEELINGS,esc,today,addDays,dayNumber,stageName,nextFollow,csv,canTeach,cleanImageType} from './core.js';
const config=window.AFORM_CONFIG||{};
const root=document.querySelector('#app');
const icons={home:'<path d="M3 10 12 3l9 7v10H3z"/><path d="M9 20v-7h6v7"/>',folder:'<path d="M3 6h7l2 3h9v11H3z"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',chart:'<path d="M4 4v16h17M8 15l4-5 4 2 5-7"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',camera:'<rect x="3" y="6" width="18" height="14" rx="2"/><circle cx="12" cy="13" r="4"/><path d="M8 6l1-3h6l1 3"/>',export:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>'};
const icon=k=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+icons[k]+'</svg>';
const brand='<div class="brand"><div class="mark">A</div><div><strong>健康观察档案</strong><small>古中医阴阳五行舌 · A表</small></div></div>';
let db=null,user=null,profile={},staff=false,demo=false,teacherDemo=false,dirty=false,busy=false,cases=[],obs=[],photos=[],reviews=[],activeStage='d1',currentCase=null,lastHash='',draftProducts=[];
let signed=new Map(),toastTimer,loaded=false,authMode='login',authMessage='',loadId=0;
const live=()=>config.ready===true;
const isTeacher=()=>demo?teacherDemo:staff;
function notify(message){const e=document.querySelector('#toast');e.textContent=message;e.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.style.display='none',4000);}
const checkResult=r=>{if(r.error)throw r.error;return r.data;};
function friendly(e){const m=e?.message||String(e);if(m.includes('version_conflict')||m.includes('0 rows'))return '记录已在别处更新。请先复制当前修改，再刷新核对。';if(m.includes('Invalid login'))return '邮箱或密码不正确。';if(m.includes('Email not confirmed'))return '请先在邮箱中完成验证，再回来登录。';if(m.includes('rate limit'))return '操作较频繁，请稍后重试。';if(m.includes('row-level')||m.includes('permission'))return '当前账号没有这份记录的操作权限。';if(m.includes('Failed to fetch'))return '网络连接未成功。内容仍保留在页面，请检查网络后重试。';return m;}
function errBox(message){return '<div class="error" role="alert">'+esc(message)+'</div>';}
function dateText(v){return v?esc(v.replaceAll('-','.')):'未约定';}
function cleanHash(){return location.hash.replace(/^#/,'')||'/';}
function go(path){if(dirty&&!confirm('有尚未保存的内容，确定离开吗？'))return;dirty=false;if(cleanHash()===path)render();else location.hash=path;}
function field(label,name,value='',type='text',extra=''){return '<div class="field"><label class="label" for="'+esc(name)+'">'+label+'</label><input class="input" id="'+esc(name)+'" name="'+esc(name)+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></div>';}
function area(label,name,value='',placeholder=''){return '<div class="field"><label class="label" for="'+esc(name)+'">'+label+'</label><textarea id="'+esc(name)+'" name="'+esc(name)+'" maxlength="3000" placeholder="'+esc(placeholder)+'">'+esc(value)+'</textarea></div>';}
function select(label,name,value,options){return '<div class="field"><label class="label" for="'+esc(name)+'">'+label+'</label><select id="'+esc(name)+'" name="'+esc(name)+'">'+options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return '<option value="'+esc(v)+'"'+(v===value?' selected':'')+'>'+esc(l)+'</option>';}).join('')+'</select></div>';}
function checks(name,values,options){return '<div class="check-group">'+options.map(v=>'<label class="check-pill"><input type="checkbox" name="'+name+'" value="'+esc(v)+'"'+(values?.includes(v)?' checked':'')+'>'+esc(v)+'</label>').join('')+'</div>';}
function checkbox(name,label,checked=false,help=''){return '<label class="check"><input type="checkbox" name="'+name+'"'+(checked?' checked':'')+'><span>'+label+(help?'<em>'+help+'</em>':'')+'</span></label>';}
const colors=['#416d50','#aa8550','#5d8790','#968a6e','#8c6872'];
function trend(observations){const list=observations.filter(o=>o.status==='submitted'&&o.actual_date).sort((a,b)=>a.actual_date.localeCompare(b.actual_date));if(!list.length)return '<div class="empty">提交首次观察后，这里会形成连续记录。</div>';const w=480,h=160,x=i=>40+i*(400/Math.max(1,list.length-1)),y=v=>135-(v-1)*28;let s='<svg class="chart" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="五项主观体感随日期的记录趋势">';for(let n=1;n<=5;n++)s+='<line x1="30" y1="'+y(n)+'" x2="460" y2="'+y(n)+'" stroke="#e0e5da"/><text x="10" y="'+(y(n)+4)+'" font-size="10" fill="#6b786c">'+n+'</text>';ITEMS.forEach(([key],idx)=>{let prev=null;list.forEach((o,i)=>{const v=o.data?.ratings?.[key];if(!v){prev=null;return;}if(prev)s+='<line x1="'+x(prev.i)+'" y1="'+y(prev.v)+'" x2="'+x(i)+'" y2="'+y(v)+'" stroke="'+colors[idx]+'" stroke-width="2"/>';s+='<circle cx="'+x(i)+'" cy="'+y(v)+'" r="3" fill="'+colors[idx]+'"/>';prev={i,v};});});list.forEach((o,i)=>s+='<text x="'+x(i)+'" y="156" text-anchor="middle" font-size="10" fill="#6b786c">'+esc(o.actual_date.slice(5))+'</text>');return s+'</svg><div class="legend">'+ITEMS.map(([,l],i)=>'<span><i style="background:'+colors[i]+'"></i>'+l+'</span>').join('')+'</div><p class="small muted mt mb">本人主观评分 · 1 差，5 很好；未评的数据不连接。</p>';}
function examplePhoto(label,day){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="500" height="500" viewBox="0 0 500 500"><rect width="500" height="500" fill="#e8e5dc"/><rect x="65" y="62" width="370" height="376" rx="14" fill="#f7f4ec" stroke="#bdc8b6"/><path d="M165 230h170v110H165zM195 230l15-25h80l15 25" fill="none" stroke="#8b9e82" stroke-width="4"/><circle cx="250" cy="283" r="34" fill="none" stroke="#8b9e82" stroke-width="4"/><text x="250" y="130" font-size="24" text-anchor="middle" fill="#244938" font-family="sans-serif">'+label+'</text><text x="250" y="170" font-size="18" text-anchor="middle" fill="#777e6d" font-family="sans-serif">'+day+'</text><text x="250" y="394" font-size="16" text-anchor="middle" fill="#777e6d" font-family="sans-serif">演示示意 · 非真实舌照</text></svg>');}
function seedDemo(){const d=addDays(today(),-6);cases=[{id:'demo-1',code:'A260001',name:'林女士',kind:'client',created_on:d,class_name:'第五期 · 泉州',partner_name:'演示学员',contact:'',consent_record:true,consent_photo:true,consent_teaching:true,version:1,owner_id:'demo',baseline:{needs:[NEEDS[0]],feelings:['睡眠不稳'],wish:'记录日常作息和精神状态',detail:'本条为虚构示例。',allergy:'未填写',meds:'未填写'}},{id:'demo-2',code:'A260002',name:'我的记录',kind:'self',created_on:addDays(today(),-1),class_name:'第五期 · 泉州',partner_name:'演示学员',contact:'',consent_record:true,consent_photo:false,consent_teaching:false,version:1,owner_id:'demo',baseline:{}}];obs=[1,3,7].map((n,i)=>({id:'demo-o'+n,case_id:'demo-1',stage:'d'+n,actual_date:addDays(d,n-1),status:'submitted',version:1,data:{ratings:{spirit:[3,3,4][i],sleep:[2,3,3][i],appetite:[3,4,3][i],bowel:[3,3,4][i],mood:[3,4,4][i]},quote:'示例：按实际情况记录，不以变化判定疗效。',tongue:{gloss:'待定',strength:'待定',coating:'待定',source:'未观察'},nextDate:addDays(d,13)}}));photos=[{id:'demo-p1',file_no:'P001',case_id:'demo-1',stage:'d1',taken_on:d,url:examplePhoto('首次观察','第 1 天'),uploader_name:'演示学员'},{id:'demo-p2',file_no:'P002',case_id:'demo-1',stage:'d7',taken_on:addDays(d,6),url:examplePhoto('再次观察','第 7 天'),uploader_name:'演示学员'}];reviews=[{case_id:'demo-1',org_status:'pending',tags:['连续观察'],comment:'此处为老师独立整理的教学笔记。'}];profile={display_name:'演示学员',class_name:'第五期 · 泉州'};loaded=true;}
function beginDemo(teacher=false){demo=true;teacherDemo=teacher;dirty=false;seedDemo();go(teacher?'/collect':'/home');}
function footer(){return '<footer class="site-foot"><div>何华清 · 古中医阴阳五行舌<br>用于学习与状态观察，不作为诊断或疗效证明。</div><span><a href="../">中医栏目</a> · <a href="#/privacy">记录与隐私说明</a> · A表 V1</span></footer>';}
function welcome(){return '<div class="wrap"><header class="site-head">'+brand+'<a class="text-btn" href="#/auth">登录 / 注册 ↗</a></header><main class="lead"><section><div class="eyebrow">OBSERVE · RECORD · FOLLOW UP</div><h1>每一次观察，<br>都值得认真留存。</h1><p>一人一档，持续记录。<br>学员用手机建档、上传照片、跟进回访；<br>老师在同一处看见完整的服务过程。</p><div class="actions"><button class="btn" data-action="start">'+icon('plus')+(live()?'登录 / 注册':'体验建档')+'</button><button class="btn secondary" data-action="teacher-demo">体验老师工作台</button></div><p class="small mt">'+(live()?'每人独立注册，档案与照片按权限保存。':'公开体验版 · 无需登录 · 刷新后体验记录不保留')+'</p></section><div class="hero-visual"><div class="sample"><div class="row between"><div class="row"><div class="avatar">'+icon('folder')+'</div><div><h3>一份观察档案</h3><small class="muted">手机记录 · 随时复看</small></div></div><span class="badge gold">21 天</span></div><div class="steps">'+STAGES.map((n,i)=>'<div class="step-node '+(i<3?'done':'')+'"><span>'+(i<3?'✓':n)+'</span>第'+n+'天</div>').join('')+'</div>'+trend([{status:'submitted',actual_date:'2026-10-01',data:{ratings:{spirit:3,sleep:2,appetite:3,bowel:3,mood:3}}},{status:'submitted',actual_date:'2026-10-03',data:{ratings:{spirit:3,sleep:3,appetite:4,bowel:3,mood:4}}},{status:'submitted',actual_date:'2026-10-07',data:{ratings:{spirit:4,sleep:3,appetite:3,bowel:4,mood:4}}}])+'<footer>界面示例 · 虚构数据，仅展示记录方式</footer></div></div></main><section class="feature-strip"><div><b>01</b><section><h3>扫码，建立一份档案</h3><p>本人或服务对象，基本信息填写一次。</p></section></div><div><b>02</b><section><h3>拍照，补充每次观察</h3><p>照片、体感和回访，沿时间保存。</p></section></div><div><b>03</b><section><h3>汇总，看见服务过程</h3><p>老师查看记录，筛选导出授权案例。</p></section></div></section>'+footer()+'</div>';}
function shell(html,active='home'){const teacher=isTeacher();const nav=[['home','/home','folder','我的档案'],['due','/due','clock','待跟进'],...(teacher?[['collect','/collect','chart','数据汇总']]:[]),['account','/account','user','我的账号']];const name=demo?'演示学员':profile.display_name||'学员';return (demo?'<div class="demo-banner"><span>体验模式 · 虚构示例，编辑仅保留在当前页面，不上传</span><button data-action="exit-demo">退出体验</button></div>':'')+'<div class="app-shell"><aside class="sidebar">'+brand+'<nav>'+nav.map(([k,url,ic,l])=>'<a class="navitem '+(active===k?'active':'')+'" href="#'+url+'">'+icon(ic)+l+'</a>').join('')+'</nav><div class="sidebar-bottom"><strong>'+esc(name)+'</strong><br>'+esc(profile.class_name||'欢迎使用观察档案')+'<div class="divider"></div>学习 · 观察 · 如实记录<br><a href="#/privacy">记录与隐私说明 ↗</a></div></aside><section class="workspace"><header class="app-header"><div class="mobile-brand">'+brand+'</div><span class="small muted desktop-only">A表 / '+(teacher?'老师工作台':'学员工作台')+'</span><div class="row gap8">'+(demo?'<button class="text-btn" data-action="toggle-role">'+(teacher?'学员视角':'老师视角')+'</button>':'<span class="small">'+esc(name)+'</span>')+'<span class="badge outline">'+(demo?'体验版':teacher?'老师':'学员')+'</span></div></header><main class="content">'+html+'</main></section></div><nav class="bottom-nav"><a href="#/home" class="'+(active==='home'?'active':'')+'">'+icon('folder')+'档案</a><a href="#/due" class="'+(active==='due'?'active':'')+'">'+icon('clock')+'跟进</a><a href="#/new"><span class="add">'+icon('plus')+'</span>建档</a><a href="#'+(teacher?'/collect':'/account')+'" class="'+(['collect','account'].includes(active)?'active':'')+'">'+icon(teacher?'chart':'user')+(teacher?'汇总':'我的')+'</a></nav>';}
async function fetchAll(table,columns='*'){let out=[],start=0;for(;;){const r=await db.from(table).select(columns).range(start,start+499);const rows=checkResult(r)||[];out.push(...rows);if(rows.length<500)break;start+=500;}return out;}
async function refresh(){if(demo)return;if(!user)return;[cases,obs,photos]=await Promise.all([fetchAll('cases'),fetchAll('observations'),fetchAll('photos')]);reviews=staff?await fetchAll('teacher_reviews'):[];cases.sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));loaded=true;}
function recordRow(c){const items=obs.filter(o=>o.case_id===c.id),next=nextFollow(c,items);return '<a class="record" href="#/case/'+esc(c.id)+'"><div class="record-avatar">'+esc(c.name.slice(0,1))+'</div><div class="grow"><h3>'+esc(c.name)+' <span class="badge outline">'+(c.kind==='self'?'本人':'服务对象')+'</span></h3><p>'+esc(c.code)+' · '+esc(c.class_name||'未填班级')+'</p><div class="record-steps">'+STAGES.map(n=>'<i class="'+(items.some(o=>o.stage==='d'+n&&o.status==='submitted')?'done':'')+'"></i>').join('')+'</div></div><div class="record-meta">'+(next?'<span class="badge '+(next.date<=today()?'gold':'outline')+'">'+(next.date<=today()?'待跟进':'下次')+' '+dateText(next.date.slice(5))+'</span>':'<span class="badge">本阶段已记录</span>')+'<span>建档 '+dateText(c.created_on)+'</span></div><span class="arrow">›</span></a>';}
function dashboard(due=false){const dueCases=cases.filter(c=>{const n=nextFollow(c,obs);return n&&n.date<=today();});const days=cases.reduce((n,c)=>n+obs.filter(o=>o.case_id===c.id&&o.status==='submitted').length,0);return shell('<div class="page-heading"><div><div class="eyebrow">YOUR OBSERVATION RECORDS</div><h1>'+(due?'今天，继续跟进':'我的观察档案')+'</h1><p>'+(due?'按已约定日期或阶段计划整理。':'为自己，也为每一位服务对象。')+'</p></div><a href="#/new" class="btn">'+icon('plus')+'新建档案</a></div><div class="stats"><div class="stat"><span>正在记录的档案</span><strong>'+cases.length+'</strong><small>份</small></div><div class="stat"><span>待跟进</span><strong>'+dueCases.length+'</strong><small>份</small></div><div class="stat"><span>已提交观察</span><strong>'+days+'</strong><small>次</small></div></div><div class="filters"><input class="input" id="search" type="search" placeholder="搜索称呼、档案编号、班级" aria-label="搜索档案"><select id="kind-filter" aria-label="档案类型"><option value="">全部类型</option><option value="client">服务对象</option><option value="self">本人记录</option></select></div><div id="record-list" class="record-list" data-due="'+due+'">'+(due?dueCases:cases).map(recordRow).join('')+(!cases.length?'<div class="empty"><h3>开始第一份记录</h3><p>先建档，再按时间补充观察与照片。</p><a class="btn" href="#/new">新建档案</a></div>':'')+'</div>'+(!dueCases.length&&due?'<p class="empty">暂时没有到期的跟进记录。</p>':''),due?'due':'home');}
function newForm(c=null){const b=c?.baseline||{};return '<a class="back" href="#'+(c?'/case/'+c.id:'/home')+'">← 返回档案</a><div class="page-heading"><div><div class="eyebrow">ONE PERSON · ONE RECORD</div><h1>'+(c?'编辑基本信息':'建立一份新档案')+'</h1><p>基本信息只需填写一次，之后持续补充观察。</p></div><span class="badge">A-01</span></div><form id="case-form" class="panel" data-id="'+esc(c?.id||'')+'"><div id="form-error"></div><h3>这份档案，记录谁？</h3><div class="grid2">'+select('档案类型','kind',c?.kind||'client',[['client','服务对象'],['self','本人记录']])+field('姓名 / 称呼 <span class="gold">*</span>','name',c?.name||'','text','required maxlength="40" placeholder="可使用化名"')+field('建档日期','created_on',c?.created_on||today(),'date','required')+field('班级 / 期次','class_name',c?.class_name||profile.class_name||'','text','maxlength="80" placeholder="例如：第五期 · 泉州"')+field('记录学员 / 服务伙伴','partner_name',c?.partner_name||profile.display_name||'','text','maxlength="60"')+field('联系方式（选填）','contact',c?.contact||'','text','maxlength="80" placeholder="按本人意愿填写"')+'</div><details'+(c?' open':'')+'><summary>服务需求与首次了解 <span class="small muted">选填</span></summary><div class="field"><span class="label">本次服务需求</span>'+checks('needs',b.needs,NEEDS)+'</div><div class="field"><span class="label">当下体感</span>'+checks('feelings',b.feelings,FEELINGS)+'</div>'+area('最希望记录或改善的方面','wish',b.wish)+area('目前具体怎样','detail',b.detail)+area('过敏情况','allergy',b.allergy)+area('在用药 / 产品','meds',b.meds)+area('本人补充','extra',b.extra)+'</details><div class="form-section"><h3>先征得本人同意，再记录</h3>'+checkbox('consent_record','已取得本人同意建立记录，并由负责学员及何华清老师查看。<span class="gold">*</span>',c?.consent_record,'用于本次观察与跟进；为他人建档时，请先当面说明。')+checkbox('consent_photo','同意拍摄与私密保存观察照片。',c?.consent_photo,'可选；不同意不影响文字记录。')+checkbox('consent_teaching','同意将去除个人标识的记录用于教学案例。',c?.consent_teaching,'独立选择，默认不同意；之后可以在档案中撤回。')+'</div><p class="small muted">用于学习与状态观察，不作为诊断或疗效证明。</p><button class="btn full" type="submit">'+(c?'保存基本信息':'保存并进入首次观察')+'</button></form>';}
async function saveCase(form){const f=new FormData(form),id=form.dataset.id,c=cases.find(x=>x.id===id);if(!f.has('consent_record'))throw Error('请先征得本人同意，并勾选建档授权。');const payload={kind:f.get('kind'),name:String(f.get('name')).trim(),created_on:f.get('created_on'),class_name:f.get('class_name'),partner_name:f.get('partner_name'),contact:f.get('contact'),consent_record:true,consent_photo:f.has('consent_photo'),consent_teaching:f.has('consent_teaching'),baseline:{needs:f.getAll('needs'),feelings:f.getAll('feelings'),wish:f.get('wish'),detail:f.get('detail'),allergy:f.get('allergy'),meds:f.get('meds'),extra:f.get('extra')}};if(!payload.name)throw Error('请填写姓名或称呼。');if(demo){if(c)Object.assign(c,payload,{version:c.version+1});else{payload.id='demo-'+crypto.randomUUID();payload.code='A'+Math.random().toString(36).slice(2,9).toUpperCase();payload.owner_id='demo';payload.version=1;cases.unshift(payload);}}else if(c){checkResult(await db.from('cases').update({...payload,version:c.version+1}).eq('id',id).eq('version',c.version).select().single());}else{Object.assign(payload,checkResult(await db.from('cases').insert(payload).select().single()));}dirty=false;await refresh();notify(demo?'体验档案已保留在当前页面':'档案已保存到云端');activeStage='d1';go('/case/'+(id||payload.id));}
function ratingControls(r={}){return '<div class="ratings">'+ITEMS.map(([k,l])=>'<div class="rating-row"><span>'+l+'</span><div class="rating-buttons" role="group" aria-label="'+l+'评分">'+[1,2,3,4,5,0].map(n=>'<button type="button" data-rating="'+k+'" data-value="'+n+'" class="'+((r[k]||0)===n?'selected':'')+'" aria-pressed="'+((r[k]||0)===n)+'">'+(n||'未评')+'</button>').join('')+'<input type="hidden" name="rating_'+k+'" value="'+(r[k]||0)+'"></div></div>').join('')+'</div>';}
function productsHTML(rows=[]){return '<div id="product-rows">'+rows.map((p,i)=>'<div class="product-row" data-index="'+i+'"><div class="row between"><strong class="small">'+esc(p.name)+'</strong><button type="button" class="text-btn" data-remove-product="'+i+'">移除</button></div><input type="hidden" name="product_name_'+i+'" value="'+esc(p.name)+'"><div class="grid2">'+field('实际使用时间','product_time_'+i,p.time||'','text','maxlength="60"')+field('每次量','product_amount_'+i,p.amount||'','text','maxlength="30"')+field('单位','product_unit_'+i,p.unit||'','text','maxlength="20"')+field('每日次数','product_times_'+i,p.perDay||'','text','maxlength="20"')+'</div>'+checkbox('product_unused_'+i,'未使用',p.unused)+'</div>').join('')+'</div>';}
function readProducts(form){return Array.from(form.querySelectorAll('.product-row')).map(row=>{const i=row.dataset.index,f=new FormData(form);return {name:f.get('product_name_'+i),time:f.get('product_time_'+i),amount:f.get('product_amount_'+i),unit:f.get('product_unit_'+i),perDay:f.get('product_times_'+i),unused:f.has('product_unused_'+i)};});}
function stageForm(c,stage){const o=obs.find(x=>x.case_id===c.id&&x.stage===stage),d=o?.data||{},t=d.tongue||{},isOwner=demo||c.owner_id===user?.id,selected=photos.filter(p=>p.case_id===c.id&&p.stage===stage);draftProducts=d.products||[];return '<form id="observation-form" class="panel" data-id="'+esc(o?.id||'')+'"><div id="form-error"></div><div class="form-top"><div><h2>'+stageName(stage)+'</h2><p>'+(o?'上次保存 '+dateText(o.actual_date)+' · '+(o.status==='submitted'?'已提交':'草稿'):'本次尚未记录')+'</p></div>'+field('实际记录日期','actual_date',o?.actual_date||today(),'date','required max="'+today()+'"')+'</div><fieldset style="border:0;padding:0;margin:0;min-width:0" '+(!isOwner?'disabled':'')+'><div class="form-section"><h3>五项体感，由本人评分</h3><p class="scale-label">1 差 · 2 偏差 · 3 一般 · 4 较好 · 5 很好</p>'+ratingControls(d.ratings)+'</div><div class="form-section"><h3>舌象照片</h3><p class="small muted">尽量同一时间段、自然光、同一角度，不美颜、不滤镜。</p><div class="photo-grid">'+selected.map(photoThumb).join('')+'</div>'+(c.consent_photo?'<div class="upload">'+icon('camera')+'<div class="row" style="justify-content:center;margin-top:12px"><button type="button" class="btn tiny secondary" data-action="pick-photo"'+(!isOwner?' disabled':'')+'>选择舌象照片</button><button type="button" class="btn tiny soft" data-action="take-photo"'+(!isOwner?' disabled':'')+'>拍摄舌象</button></div><p>每次最多 3 张 · JPG / PNG / WebP · 单张 ≤ 10MB<br>'+(!o?'请先保存本次观察，再添加照片。':'照片只提供给有权限的记录人和老师。')+'</p><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><input id="camera-input" type="file" accept="image/*" capture="environment" hidden></div>':'<div class="well"><p>本档案尚未同意保存照片。如本人愿意，可在“基本信息”中修改授权。</p></div>')+'</div><details><summary>舌象人工观察</summary><div class="grid2">'+select('光泽','gloss',t.gloss||'待定',['待定','好','不好'])+select('力度','strength',t.strength||'待定',['待定','好','不好'])+select('力度观察来源','source',t.source||'未观察',['未观察','现场动作观察','本人描述'])+select('苔象完整度','coating',t.coating||'待定',['待定','好','不好'])+select('传统课程三判记录','yinyang',t.yinyang||'待定',['待定','阳舌','阴舌'])+select('整体形态','form',t.form||'待定',['待定','金','木','土','水','组合'])+select('课程主轴记录','axis',t.axis||'待定',['待定','火扶正','土水固本','金木起势'])+'</div><p class="small muted">仅作课程学习观察。静态图片无法判断动作力度；未观察请选择“待定”。</p>'+(stage!=='d1'?'<div class="grid2">'+['光泽','力度','苔象完整度','整体形态'].map((x,i)=>select(x+'与首次相比','compare_'+i,d.compare?.[i]||'未评',['未评','主观感觉改善','不变','主观感觉变差'])).join('')+'</div>':'')+'</details><details><summary>实际使用与日常行动</summary><div class="grid2">'+select('实际使用','usage',d.usage||'未核对',['未核对','按原记录','有变化','未使用'])+select('日常行动','action',d.action||'未核对',['未核对','已落实','部分落实','未落实'])+'</div>'+area('变化说明 / 具体行动','usageNote',d.usageNote)+'<h3>产品实际使用记录</h3><p class="small muted">按产品标签及个人情况核对。只记录实际情况，不自动生成用量。</p>'+productsHTML(draftProducts)+'<div class="row mt"><select id="product-select" aria-label="选择要记录的产品">'+PRODUCTS.map(p=>'<option>'+p+'</option>').join('')+'<option value="other">其他产品</option></select><button type="button" class="btn tiny secondary" data-action="add-product">添加</button></div></details><div class="form-section"><h3>本人反馈与下一次约定</h3>'+area('本人原话','quote',d.quote,'如实记录本人感受')+'<div class="grid2">'+select('本次处理','handling',d.handling||'待定',['待定','维持','复核','调整','暂停','咨询'])+select('下次联系方式','nextMethod',d.nextMethod||'微信',['微信','电话','面访'])+'</div>'+area('原因与行动','handlingReason',d.handlingReason)+field('下次跟进日期','nextDate',d.nextDate||addDays(c.created_on,({d1:2,d3:6,d7:13,d14:20,d21:27})[stage]),'date')+'</div>'+(stage==='d21'?'<details open><summary>21 天复盘</summary><div class="grid2">'+select('生活体感变化','lifeChange',d.lifeChange||'未评',['未评','主观感觉改善','不变','主观感觉变差'])+select('舌象变化','tongueChange',d.tongueChange||'未评',['未评','主观感觉改善','不变','主观感觉变差'])+'</div>'+area('伙伴复盘','partnerReview',d.partnerReview)+select('后续服务','nextService',d.nextService||'结束本阶段',['结束本阶段','继续服务','专业咨询'])+area('下次服务重点','nextFocus',d.nextFocus)+'</details>':'')+'</fieldset>'+(isOwner?'<div class="savebar"><small id="save-state">'+(demo?'体验模式，未上传云端':o?'已读取云端记录':'尚未保存')+'</small><div class="row gap8"><button type="submit" name="intent" value="draft" class="btn secondary">存草稿</button><button type="submit" name="intent" value="submitted" class="btn">保存并提交</button></div></div>':'<div class="notice">您正在查看学生原始记录。老师评语请填写在“老师整理”中。</div>')+'</form>';}
function photoThumb(p){const url=p.url||signed.get(p.storage_path)||'';return '<div class="photo-thumb">'+(url?'<img src="'+esc(url)+'" alt="'+esc(stageName(p.stage)+' '+p.taken_on)+'" data-zoom="'+esc(url)+'">':'<div class="empty">照片载入中</div>')+'<small>'+dateText(p.taken_on)+' · '+esc(p.file_no)+'</small>'+((demo||currentCase?.owner_id===user?.id)?'<button type="button" data-delete-photo="'+esc(p.id)+'" aria-label="删除此照片">×</button>':'')+'</div>';}
async function signPhotos(list){if(demo||!list.length)return;const paths=list.map(p=>p.storage_path);const r=await db.storage.from('case-photos').createSignedUrls(paths,120);checkResult(r)?.forEach(p=>{if(p.signedUrl)signed.set(p.path,p.signedUrl);});}
function comparison(c){const list=photos.filter(p=>p.case_id===c.id).sort((a,b)=>a.taken_on.localeCompare(b.taken_on));if(!list.length)return '<div class="empty"><h3>从第一次拍照开始</h3><p>在观察记录中上传照片后，即可选择两个日期对比。</p></div>';const option=p=>'<option value="'+esc(p.id)+'">'+dateText(p.taken_on)+' · '+stageName(p.stage)+'</option>';return '<h2>在同一条件下，认真对照</h2><p class="small muted">日期和拍摄条件会影响照片外观。对照用于观察记录，不直接推断疗效。</p><div class="compare-grid">'+[0,1].map((n)=>{const p=list[n===0?0:list.length-1];return '<figure><div class="field"><label class="label" for="compare-'+n+'">'+(n===0?'较早记录':'再次记录')+'</label><select id="compare-'+n+'" data-compare="'+n+'">'+list.map(x=>option(x).replace('value="'+esc(x.id)+'"','value="'+esc(x.id)+'"'+(x.id===p.id?' selected':''))).join('')+'</select></div><img id="compare-image-'+n+'" src="'+esc(p.url||signed.get(p.storage_path)||'')+'" alt="所选日期的观察照片" data-zoom="'+esc(p.url||signed.get(p.storage_path)||'')+'"><figcaption id="compare-caption-'+n+'">'+dateText(p.taken_on)+' · '+stageName(p.stage)+'<br>记录人：'+esc(p.uploader_name||c.partner_name)+'</figcaption></figure>';}).join('')+'</div><div class="section-head"><h2>五项体感趋势</h2><span class="badge outline">本人评分</span></div><div class="trend-wrap">'+trend(obs.filter(o=>o.case_id===c.id))+'</div>';}
function detailsPage(c,tab='record'){const items=obs.filter(o=>o.case_id===c.id),owned=demo||c.owner_id===user?.id;return shell('<a class="back" href="#'+(isTeacher()?'/collect':'/home')+'">← 返回档案列表</a><div class="page-heading"><div><div class="kicker">'+esc(c.code)+' · '+esc(c.class_name||'观察档案')+'</div><h1>'+esc(c.name)+' <span class="badge outline">'+(c.kind==='self'?'本人记录':'服务对象')+'</span></h1><p>建档 '+dateText(c.created_on)+' · 记录人 '+esc(c.partner_name||'未填写')+'</p></div><span class="badge gold">'+items.filter(x=>x.status==='submitted').length+' 次观察</span></div><div class="tabs">'+[['record','观察记录'],['compare','舌象对比'],['info','基本信息'],...(isTeacher()?[['review','老师整理']]:[])].map(([k,l])=>'<button data-tab="'+k+'" class="'+(k===tab?'active':'')+'">'+l+'</button>').join('')+'</div>'+(tab==='record'?'<div class="stage-rail">'+STAGES.map(n=>'<button class="stage-button '+(activeStage==='d'+n?'active ':'')+(items.some(o=>o.stage==='d'+n&&o.status==='submitted')?'done':'')+'" data-stage="d'+n+'"><strong>'+(n===1?'首次':'第'+n+'天')+'</strong><small>'+dateText(addDays(c.created_on,n-1).slice(5))+'</small></button>').join('')+'</div>'+stageForm(c,activeStage):tab==='compare'?comparison(c):tab==='review'?reviewForm(c):'<div class="panel"><h2>档案与授权</h2><dl><dt class="small muted">建档类型</dt><dd>'+esc(c.kind==='self'?'本人记录':'服务对象')+'</dd><dt class="small muted">联系方式</dt><dd>'+esc(c.contact||'未填写')+'</dd><dt class="small muted">拍照保存</dt><dd>'+(c.consent_photo?'已同意':'未同意')+'</dd><dt class="small muted">匿名教学案例</dt><dd>'+(c.consent_teaching?'已同意，可撤回':'未同意')+'</dd></dl><div class="divider"></div><h3>首次需求</h3><p class="small">'+esc((c.baseline?.needs||[]).join('、')||'未填写')+'</p><p class="small">'+esc(c.baseline?.wish||'')+'</p><p class="small muted">学生只可查看自己负责的档案，老师可查看本人已同意采集的记录。</p>'+(owned?'<div class="stack mt"><a class="btn secondary" href="#/edit/'+esc(c.id)+'">编辑信息与授权</a>'+(c.consent_teaching?'<button class="text-btn" data-action="revoke">撤回教学案例授权</button>':'')+'<button class="text-btn" style="color:var(--red)" data-action="request-delete">'+(c.deletion_requested?'已提交删除申请':'申请删除这份档案')+'</button></div>':'')+'</div>'),'home');}
function reviewForm(c){const r=reviews.find(x=>x.case_id===c.id)||{};return '<form id="review-form" class="panel"><div id="form-error"></div><h2>保留原记录，单独做整理</h2><p class="small muted">老师评语不会改写学生的观察原文。</p>'+select('整理状态','org_status',r.org_status||'pending',[['pending','待整理'],['organized','已整理']])+field('主题标签（以逗号分隔）','tags',(r.tags||[]).join('，'),'text','maxlength="200" placeholder="例如：作息记录、连续观察"')+area('老师评语','comment',r.comment)+'<button class="btn" type="submit">保存整理</button><div class="divider"></div>'+(canTeach(c)?'<h3>已获独立教学授权</h3><p class="small muted">导出的案例默认只含匿名编号、日期与五项评分，不含姓名、电话、原始自由文本或照片。</p><button class="btn secondary" type="button" data-action="case-export">生成匿名案例页</button>':'<div class="well"><p>本人尚未同意教学案例使用。本档案不会纳入教学案例库。</p></div>')+'</form>';}
function collection(){if(!isTeacher())return shell('<div class="empty"><h2>老师管理入口</h2><p>此账号尚未开通老师权限。</p></div>');const classes=[...new Set(cases.map(c=>c.class_name).filter(Boolean))],partners=[...new Set(cases.map(c=>c.partner_name).filter(Boolean))];return shell('<div class="page-heading"><div><div class="eyebrow">TEACHER WORKSPACE</div><h1>记录与案例汇总</h1><p>按学员与班级汇总，完整保留观察过程。</p></div><button class="btn secondary" data-action="csv-export">'+icon('export')+'导出</button></div><div class="stats"><div class="stat"><span>授权采集档案</span><strong>'+cases.length+'</strong><small>份</small></div><div class="stat"><span>参与记录学员</span><strong>'+new Set(cases.map(c=>c.owner_id)).size+'</strong><small>位</small></div><div class="stat"><span>教学案例授权</span><strong>'+cases.filter(canTeach).length+'</strong><small>份</small></div></div><div class="filters"><input class="input" id="collect-search" aria-label="搜索全部档案" placeholder="搜索姓名、编号"><select id="class-filter" aria-label="按班级筛选"><option value="">全部班级</option>'+classes.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><select id="student-filter" aria-label="按记录学员筛选"><option value="">全部学员</option>'+partners.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><select id="consent-filter" aria-label="案例授权筛选"><option value="">全部记录</option><option value="yes">已授权教学案例</option><option value="no">未授权教学案例</option><option value="delete">删除申请</option></select><select id="stage-filter" aria-label="观察阶段筛选"><option value="">全部阶段</option>'+STAGES.map(n=>'<option value="d'+n+'">已提交第'+n+'天</option>').join('')+'</select></div><div class="grid2"><div class="field"><label class="label" for="date-start">建档起始日期</label><input class="input" type="date" id="date-start"></div><div class="field"><label class="label" for="date-end">建档截止日期</label><input class="input" type="date" id="date-end"></div></div><div class="section-head"><h2>档案目录</h2><small class="muted" id="collect-count">'+cases.length+' 份记录</small></div><div id="collect-list" class="record-list">'+cases.map(recordRow).join('')+'</div>'+(!cases.length?'<div class="empty">学员提交后，记录会出现在这里。</div>':''),'collect');}
function filteredCollection(){const val=id=>document.getElementById(id)?.value||'',q=val('collect-search').toLowerCase();return cases.filter(c=>(!q||(c.name+c.code).toLowerCase().includes(q))&&(!val('class-filter')||c.class_name===val('class-filter'))&&(!val('student-filter')||c.partner_name===val('student-filter'))&&(!val('date-start')||c.created_on>=val('date-start'))&&(!val('date-end')||c.created_on<=val('date-end'))&&(val('consent-filter')!=='yes'||c.consent_teaching)&&(val('consent-filter')!=='no'||!c.consent_teaching)&&(val('consent-filter')!=='delete'||c.deletion_requested)&&(!val('stage-filter')||obs.some(o=>o.case_id===c.id&&o.stage===val('stage-filter')&&o.status==='submitted')));}
function authPage(){
  const signup=authMode==='signup',forgot=authMode==='forgot',setup=authMode==='setup';
  const title=setup?'设置您的登录密码':forgot?'找回登录密码':signup?'注册新账号':'欢迎回来';
  const intro=signup?'用您自己的邮箱建立账号，记录自己，也为服务对象建档。':'老师与学员使用同一入口，登录后按各自权限查看档案。';
  const tabs=!forgot&&!setup?'<div class="auth-tabs" role="tablist" aria-label="账号入口"><button type="button" role="tab" aria-selected="'+(!signup)+'" data-auth="login">登录</button><button type="button" role="tab" aria-selected="'+signup+'" data-auth="signup">注册</button></div>':'';
  return '<div class="wrap"><header class="site-head"><a href="#/">'+brand+'</a><a class="text-btn" href="#/">返回首页</a></header><div class="auth-shell"><div class="panel"><div class="eyebrow">YOUR PERSONAL ACCOUNT</div><h1 style="font-size:30px;margin-top:14px">'+title+'</h1><p class="small muted">'+intro+'</p>'+tabs+(!live()?'<div class="notice mb">当前为公开体验版，登录注册与云端保存尚未开通。可直接体验下方两种视角，无需填写真实账号。</div>':'')+'<form id="auth-form">'+(authMessage?'<div class="notice mb">'+esc(authMessage)+'</div>':'')+'<div id="form-error"></div>'+(signup?field('您的姓名或称呼','display_name','','text','required maxlength="60" autocomplete="name"'):'')+field('邮箱','email',setup?user?.email||'':'','email','required autocomplete="email" '+(setup?'readonly':'placeholder="请输入您自己的邮箱"'))+(!forgot?field(setup||signup?'设置密码':'密码','password','','password','required minlength="8" autocomplete="'+(setup||signup?'new-password':'current-password')+'" placeholder="至少 8 位"'):'')+(setup||signup?field('再次输入密码','confirm_password','','password','required minlength="8" autocomplete="new-password"'):'')+'<button class="btn full" type="submit" '+(!live()?'disabled':'')+'>'+(setup?'保存密码并进入档案':forgot?'发送重设邮件':signup?'注册并验证邮箱':'登录并进入档案')+'</button></form><div class="row between mt"><span class="small muted">每人一个账号，档案按权限查看。</span>'+(!signup&&!setup?'<button class="text-btn" data-auth="'+(forgot?'login':'forgot')+'">'+(forgot?'返回登录':'忘记密码')+'</button>':'')+'</div>'+(!live()?'<div class="divider"></div><div class="stack"><button class="btn secondary full" data-action="student-demo">体验学员建档与舌象上传</button><button class="btn soft full" data-action="teacher-demo">体验老师汇总工作台</button></div>':'')+'<p class="small muted mt mb">正式开通后，学员查看自己建立的档案；老师按本人授权汇总。老师权限由后台设置。</p></div></div>'+footer()+'</div>';
}
function accountPage(){return shell('<div class="page-heading"><div><div class="eyebrow">ACCOUNT & ACCESS</div><h1>我的账号</h1><p>让每一份记录，都能找到负责的人。</p></div></div><form id="profile-form" class="panel"><div id="form-error"></div>'+field('学员姓名','display_name',profile.display_name||'','text','required maxlength="60"')+field('班级 / 期次','class_name',profile.class_name||'','text','maxlength="80"')+'<p class="small muted">账号身份：'+(demo?'体验账号':staff?'老师':'学员')+'<br>邮箱：'+esc(demo?'未使用真实账号':user?.email||'')+'</p><button type="submit" class="btn">保存资料</button><div class="divider"></div><h3>记录属于谁</h3><p class="small muted">学员仅可查看自己建立的档案；经本人同意后，老师统一采集和查看。教学案例授权独立设置，可以在档案中撤回。</p><a class="small" href="#/privacy">查看记录与隐私说明 ↗</a><div class="divider"></div><button class="btn secondary" type="button" data-action="'+(demo?'exit-demo':'logout')+'">'+(demo?'退出体验':'退出登录')+'</button></form>','account');}
function privacy(){return '<div class="wrap"><header class="site-head"><a href="#/">'+brand+'</a><a href="#/" class="text-btn">返回首页</a></header><article class="legal"><h1>记录与隐私</h1><p>本网站用于古中医阴阳五行舌课程的学习、状态观察与服务跟进。照片和评分不会自动形成诊断、用量建议或疗效结论。</p><h2>先获得同意，再建档</h2><p>学员为别人记录时，应先说明采集项目、用途与查看范围。姓名可用称呼或化名，联系方式选填。不采集身份证号或家庭住址。</p><h2>谁可以进入与查看</h2><p>入口只向老师邀请的学员开放，不开放自行注册。正式版中，负责记录的学员与获授权的老师可以查看档案；其他学员不能查看。图片保存在私有存储中，查看链接限时有效。</p><h2>案例授权单独选择</h2><p>建立档案、保存照片、匿名教学案例是分开的授权。教学案例默认不同意，可以在档案中撤回。公开分享案例前仍需逐项核对照片和文字中可能识别个人的信息。</p><h2>修改与删除</h2><p>记录学员可修改本人负责的档案、撤回教学授权，并提交删除申请。老师的整理与学生原始记录分开保存。已导出到网站之外的文件需由导出者另外管理。</p><h2>当前版本状态</h2><p>'+esc(config.notice||'请按当前页面提示使用。')+'</p><p>体验模式使用虚构示例。新填内容及所选图片仅保留在当前页面内存，刷新或退出后会丢失，不发送到老师后台。请勿在体验版输入真实个人健康信息。</p></article>'+footer()+'</div>';}
async function render(){const token=++loadId;const path=cleanHash();lastHash=location.hash;if(path==='/privacy'){root.innerHTML=privacy();return;}if(path==='/auth'){root.innerHTML=authPage();return;}if(path==='/'&&!demo&&!user){root.innerHTML=welcome();return;}if(!demo&&!user){root.innerHTML=authPage();return;}if(!loaded){root.innerHTML='<div class="loading"><div class="mark">A</div><p>正在读取您的档案…</p></div>';try{await refresh();}catch(e){root.innerHTML=shell(errBox(friendly(e))+'<button class="btn mt" data-action="reload">重新读取</button>');return;}}if(token!==loadId)return;const parts=path.split('/');if(parts[1]==='case'){const c=cases.find(x=>x.id===parts[2]);if(!c){root.innerHTML=shell('<div class="empty">未找到档案，或当前账号无权查看。</div>');return;}currentCase=c;const tab=parts[3]||'record';if(tab==='review'&&!isTeacher()){root.innerHTML=shell(errBox('没有老师权限。'));return;}try{await signPhotos(photos.filter(p=>p.case_id===c.id));}catch(e){notify('部分照片暂时未载入，请重试。');}if(token!==loadId)return;root.innerHTML=detailsPage(c,tab);}else if(parts[1]==='new')root.innerHTML=shell(newForm(),'home');else if(parts[1]==='edit'){const c=cases.find(x=>x.id===parts[2]);root.innerHTML=shell(c&&(demo||c.owner_id===user?.id)?newForm(c):errBox('您没有编辑权限。'));}else if(parts[1]==='collect')root.innerHTML=collection();else if(parts[1]==='account')root.innerHTML=accountPage();else root.innerHTML=dashboard(parts[1]==='due');window.scrollTo({top:0,behavior:'instant'});}
async function saveObservation(form,intent){const c=currentCase,f=new FormData(form),existing=obs.find(o=>o.id===form.dataset.id),data={ratings:Object.fromEntries(ITEMS.map(([k])=>[k,Number(f.get('rating_'+k))||null])),tongue:Object.fromEntries(['gloss','strength','source','coating','yinyang','form','axis'].map(k=>[k,f.get(k)])),compare:Object.fromEntries([0,1,2,3].map(k=>[k,f.get('compare_'+k)||'未评'])),products:readProducts(form)};if(data.tongue.source==='未观察')data.tongue.strength='待定';['usage','action','usageNote','quote','handling','handlingReason','nextDate','nextMethod','lifeChange','tongueChange','partnerReview','nextService','nextFocus'].forEach(k=>data[k]=f.get(k)||'');const payload={case_id:c.id,stage:activeStage,actual_date:f.get('actual_date'),status:intent||'draft',data};if(demo){if(existing)Object.assign(existing,payload,{version:existing.version+1});else obs.push({...payload,id:crypto.randomUUID(),version:1});}else if(existing){checkResult(await db.from('observations').update({...payload,version:existing.version+1}).eq('id',existing.id).eq('version',existing.version).select().single());}else checkResult(await db.from('observations').insert(payload).select().single());dirty=false;await refresh();notify(demo?'体验记录已保存至当前页面':intent==='draft'?'草稿已保存到云端':'观察记录已提交');await render();}
async function compress(file){cleanImageType(file);const url=URL.createObjectURL(file);try{const im=new Image();im.src=url;await im.decode();const factor=Math.min(1,1600/Math.max(im.width,im.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*factor));canvas.height=Math.max(1,Math.round(im.height*factor));const cx=canvas.getContext('2d');cx.fillStyle='#ffffff';cx.fillRect(0,0,canvas.width,canvas.height);cx.drawImage(im,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw Error('图片处理失败，请更换一张照片。');return blob;}finally{URL.revokeObjectURL(url);}}
async function upload(files){const c=currentCase,o=obs.find(o=>o.case_id===c.id&&o.stage===activeStage);if(!o)throw Error('请先保存本次观察，再添加照片。');if(!c.consent_photo)throw Error('请先取得本人照片保存授权。');const existing=photos.filter(p=>p.case_id===c.id&&p.stage===activeStage);if(existing.length+files.length>3)throw Error('每次观察最多 3 张照片，请减少选择。');for(const file of files){const blob=await compress(file),metadata={case_id:c.id,stage:activeStage,taken_on:o.actual_date,uploader_name:profile.display_name||c.partner_name,size_bytes:blob.size,kind:'tongue'};if(demo){photos.push({...metadata,id:crypto.randomUUID(),file_no:'P'+Math.random().toString(36).slice(2,8).toUpperCase(),url:URL.createObjectURL(blob)});}else{const path=c.id+'/'+crypto.randomUUID()+'.jpg';checkResult(await db.storage.from('case-photos').upload(path,blob,{contentType:'image/jpeg',upsert:false}));try{checkResult(await db.from('photos').insert({...metadata,storage_path:path}));}catch(e){await db.storage.from('case-photos').remove([path]);throw e;}}}await refresh();notify(demo?'图片已添加到体验页面，未上传':'照片已上传并私密保存');await render();}
function dialog(html,light=false){const d=document.querySelector('#dialog');d.className=light?'lightbox':'';d.innerHTML=html;d.showModal();}
function download(content,type,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportCSV(){if(!isTeacher())throw Error('需要老师权限。');const records=filteredCollection(),rows=[['档案编号','称呼','类型','班级','记录学员','联系方式','建档日期','教学授权','观察阶段','实际日期','状态','精神','睡眠','食欲','排便','情绪','本人原话','下一回访日期','照片编号']];records.forEach(c=>{const list=obs.filter(o=>o.case_id===c.id);(list.length?list:[{}]).forEach(o=>rows.push([c.code,c.name,c.kind==='self'?'本人':'服务对象',c.class_name,c.partner_name,c.contact,c.created_on,c.consent_teaching?'同意':'不同意',o.stage?stageName(o.stage):'',o.actual_date,o.status==='submitted'?'已提交':'草稿',...ITEMS.map(([k])=>o.data?.ratings?.[k]??''),o.data?.quote||'',o.data?.nextDate||'',photos.filter(p=>p.case_id===c.id&&(!o.stage||p.stage===o.stage)).map(p=>p.file_no).join(' / ')]));});download(csv(rows),'text/csv;charset=utf-8','A表_'+(demo?'演示_':'')+'档案汇总_'+today()+'.csv');notify('已导出当前筛选的 '+records.length+' 份档案');}
async function exportCase(){if(!isTeacher())throw Error('需要老师权限。');let c=currentCase;if(!demo)c=checkResult(await db.from('cases').select('*').eq('id',c.id).single());if(!canTeach(c))throw Error('本档案尚未授权教学，或已撤回授权。');const list=obs.filter(o=>o.case_id===c.id&&o.status==='submitted').sort((a,b)=>a.actual_date.localeCompare(b.actual_date));const content='<h1>匿名观察案例 · '+esc(c.code)+'</h1><p>用于课程学习与状态观察，不作为诊断或疗效证明。</p><p>仅导出日期与本人主观评分，未包含姓名、电话、原始自由文本和照片。</p><table><thead><tr><th>日期</th><th>节点</th>'+ITEMS.map(([,l])=>'<th>'+l+'</th>').join('')+'</tr></thead><tbody>'+list.map(o=>'<tr><td>'+esc(o.actual_date)+'</td><td>'+stageName(o.stage)+'</td>'+ITEMS.map(([k])=>'<td>'+esc(o.data?.ratings?.[k]??'未评')+'</td>').join('')+'</tr>').join('')+'</tbody></table><p>1 差 · 2 偏差 · 3 一般 · 4 较好 · 5 很好；“未评”不计为分值。</p><p>生成日期：'+today()+(demo?' · 演示数据':'')+'</p>';dialog('<div class="case-print">'+content+'</div><div class="dialog-actions"><button class="btn secondary" data-action="close-dialog">返回</button><button class="btn" id="download-case">下载匿名案例</button></div>');document.querySelector('#download-case').onclick=()=>{download('<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><title>匿名观察案例 '+esc(c.code)+'</title><style>body{max-width:850px;margin:40px auto;padding:25px;font:16px/1.8 sans-serif;color:#173c33}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ddd;padding:10px}h1{font-size:26px}@media print{body{margin:0}}</style>'+content+'</html>','text/html;charset=utf-8','匿名观察案例_'+c.code+'.html');document.querySelector('#dialog').close();};}
async function saveReview(form){if(!isTeacher())throw Error('没有老师权限。');const f=new FormData(form),payload={case_id:currentCase.id,org_status:f.get('org_status'),tags:String(f.get('tags')).split(/[,，]/).map(s=>s.trim()).filter(Boolean),comment:f.get('comment'),updated_at:new Date().toISOString()};if(demo){const old=reviews.find(r=>r.case_id===currentCase.id);if(old)Object.assign(old,payload);else reviews.push(payload);}else checkResult(await db.from('teacher_reviews').upsert({...payload,updated_by:user.id}));dirty=false;await refresh();notify('整理已保存');}
async function patchCase(payload){const c=currentCase;if(demo)Object.assign(c,payload,{version:c.version+1});else checkResult(await db.from('cases').update({...payload,version:c.version+1}).eq('id',c.id).eq('version',c.version).select().single());await refresh();dirty=false;render();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');const a=e.target.closest('a[href^="#/"]');if(a){e.preventDefault();go(a.getAttribute('href').slice(1));return;}const z=e.target.closest('[data-zoom]');if(z){dialog('<img src="'+esc(z.dataset.zoom)+'" alt="观察照片放大查看"><div class="dialog-actions"><button class="btn secondary" data-action="close-dialog">关闭</button></div>',true);return;}if(!b)return;try{if(b.dataset.auth){authMode=['signup','forgot'].includes(b.dataset.auth)?b.dataset.auth:'login';authMessage='';go('/auth');return;}if(b.dataset.rating){const group=b.closest('.rating-buttons');group.querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});group.querySelector('input').value=b.dataset.value;dirty=true;return;}if(b.dataset.tab){go('/case/'+currentCase.id+'/'+b.dataset.tab);return;}if(b.dataset.stage){if(dirty&&!confirm('当前观察尚未保存，确定切换吗？'))return;activeStage=b.dataset.stage;dirty=false;render();return;}if(b.dataset.removeProduct!==undefined){const form=document.querySelector('#observation-form');draftProducts=readProducts(form);draftProducts.splice(Number(b.dataset.removeProduct),1);document.querySelector('#product-rows').outerHTML=productsHTML(draftProducts);dirty=true;return;}if(b.dataset.deletePhoto){if(!confirm('确定删除这张照片？此操作无法撤销。'))return;const p=photos.find(x=>x.id===b.dataset.deletePhoto);if(demo){if(p.url?.startsWith('blob:'))URL.revokeObjectURL(p.url);photos=photos.filter(x=>x.id!==p.id);}else{checkResult(await db.storage.from('case-photos').remove([p.storage_path]));checkResult(await db.from('photos').delete().eq('id',p.id));await refresh();}render();return;}switch(b.dataset.action){case 'start':live()?go('/auth'):beginDemo(false);break;case 'student-demo':beginDemo(false);break;case 'teacher-demo':beginDemo(true);break;case 'toggle-role':if(demo){teacherDemo=!teacherDemo;go(teacherDemo?'/collect':'/home');}break;case 'exit-demo':if(dirty&&!confirm('退出后，体验记录会丢失。确定退出吗？'))break;photos.forEach(p=>{if(p.url?.startsWith('blob:'))URL.revokeObjectURL(p.url);});demo=false;teacherDemo=false;dirty=false;cases=[];obs=[];photos=[];loaded=false;go('/');break;case 'logout':checkResult(await db.auth.signOut());user=null;loaded=false;cases=[];obs=[];photos=[];signed.clear();go('/');break;case 'reload':loaded=false;render();break;case 'pick-photo':case 'take-photo':if(dirty){notify('请先保存当前修改，再上传照片。');break;}if(!obs.some(o=>o.case_id===currentCase.id&&o.stage===activeStage)){notify('请先保存本次观察，再上传照片。');break;}document.querySelector(b.dataset.action==='pick-photo'?'#photo-input':'#camera-input').click();break;case 'add-product':{const form=document.querySelector('#observation-form');draftProducts=readProducts(form);let name=document.querySelector('#product-select').value;if(name==='other')name=prompt('请输入实际使用的产品名称');if(!name?.trim())break;draftProducts.push({name:name.trim(),time:'',amount:'',unit:'',perDay:'',unused:false});document.querySelector('#product-rows').outerHTML=productsHTML(draftProducts);dirty=true;break;}case 'csv-export':exportCSV();break;case 'case-export':await exportCase();break;case 'close-dialog':document.querySelector('#dialog').close();break;case 'revoke':if(confirm('撤回后，本档案将从教学案例库排除。确定撤回吗？')){await patchCase({consent_teaching:false});notify('已撤回教学案例授权');}break;case 'request-delete':if(confirm('提交删除申请后，老师可在后台看到申请。原记录在完成删除前仍会保留。')){await patchCase({deletion_requested:true});notify('删除申请已记录');}break;}}catch(err){notify(friendly(err));}});
document.addEventListener('input',e=>{if(e.target.closest('#case-form,#observation-form,#review-form,#profile-form')){dirty=true;const s=document.querySelector('#save-state');if(s)s.textContent='有未保存的修改';}if(e.target.id==='search')filterDashboard();if(e.target.id==='collect-search')filterCollection();});
function filterDashboard(){const due=document.querySelector('#record-list')?.dataset.due==='true',q=document.querySelector('#search')?.value.toLowerCase()||'',kind=document.querySelector('#kind-filter')?.value||'';const list=cases.filter(c=>(!q||(c.name+c.code+c.class_name).toLowerCase().includes(q))&&(!kind||c.kind===kind)&&(!due||(()=>{const n=nextFollow(c,obs);return n&&n.date<=today();})()));document.querySelector('#record-list').innerHTML=list.length?list.map(recordRow).join(''):'<div class="empty">没有符合条件的档案。</div>';}
function filterCollection(){const list=filteredCollection();document.querySelector('#collect-list').innerHTML=list.length?list.map(recordRow).join(''):'<div class="empty">没有符合条件的档案。</div>';document.querySelector('#collect-count').textContent=list.length+' 份记录';}
document.addEventListener('change',async e=>{const t=e.target;try{if(t.closest('form'))dirty=true;if(t.id==='kind-filter')filterDashboard();if(['class-filter','student-filter','consent-filter','stage-filter','date-start','date-end'].includes(t.id))filterCollection();if(t.dataset.compare!==undefined){const p=photos.find(p=>p.id===t.value),i=t.dataset.compare,im=document.querySelector('#compare-image-'+i),url=p.url||signed.get(p.storage_path)||'';im.src=url;im.dataset.zoom=url;document.querySelector('#compare-caption-'+i).innerHTML=dateText(p.taken_on)+' · '+stageName(p.stage)+'<br>记录人：'+esc(p.uploader_name||currentCase.partner_name);}if(['photo-input','camera-input'].includes(t.id)&&t.files.length){dirty=false;busy=true;notify('正在处理图片…');await upload([...t.files]);busy=false;}}catch(err){busy=false;notify(friendly(err));}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=e.target,submitter=e.submitter,buttons=[...f.querySelectorAll('button[type=submit]')];busy=true;buttons.forEach(b=>b.disabled=true);const er=f.querySelector('#form-error');if(er)er.innerHTML='';try{if(f.id==='case-form')await saveCase(f);else if(f.id==='observation-form')await saveObservation(f,submitter?.value);else if(f.id==='review-form')await saveReview(f);else if(f.id==='profile-form'){const data=new FormData(f),p={display_name:data.get('display_name'),class_name:data.get('class_name')};if(!demo)checkResult(await db.from('profiles').update(p).eq('id',user.id));Object.assign(profile,p);dirty=false;notify('资料已保存');}else if(f.id==='auth-form'){if(!live())throw Error('正式入口尚未开放，请先使用体验版。');const data=new FormData(f),email=String(data.get('email')).trim(),password=data.get('password');if(authMode==='signup'){if(password!==data.get('confirm_password'))throw Error('两次密码不一致，请重新输入。');const r=checkResult(await db.auth.signUp({email,password,options:{data:{display_name:String(data.get('display_name')||'').trim()},emailRedirectTo:location.origin+location.pathname+'#/auth'}}));if(r.session){user=r.user;await loadProfile();loaded=false;go('/home');}else{authMode='login';authMessage='请查看邮箱中的验证邮件，验证完成后用邮箱和密码登录。';render();}}else if(authMode==='setup'){if(!user)throw Error('开通链接已失效，请重新获取邮件。');if(password!==data.get('confirm_password'))throw Error('两次密码不一致，请重新输入。');checkResult(await db.auth.updateUser({password}));await loadProfile();authMode='login';authMessage='';loaded=false;go('/home');}else if(authMode==='forgot'){checkResult(await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname+'#/activate'}));authMessage='若邮箱已注册，将收到密码重设邮件。请从邮件链接设置新密码。';render();}else{const r=checkResult(await db.auth.signInWithPassword({email,password}));user=r.user;await loadProfile();loaded=false;go('/home');}}}catch(err){if(er)er.innerHTML=errBox(friendly(err));else notify(friendly(err));}finally{busy=false;buttons.forEach(b=>b.disabled=f.id==='auth-form'&&!live());}});
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{if(dirty&&!confirm('有尚未保存的修改，确定离开吗？')){history.replaceState(null,'',lastHash||'#/home');return;}dirty=false;render();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!demo&&currentCase&&!dirty&&user){signed.clear();render();}});
async function loadProfile(){try{const p=checkResult(await db.from('profiles').select('*').eq('id',user.id).maybeSingle());profile=p||{};const roles=checkResult(await db.from('user_roles').select('role').eq('user_id',user.id))||[];staff=roles.some(r=>['teacher','admin'].includes(r.role));}catch(e){user=null;profile={};staff=false;loaded=false;cases=[];obs=[];photos=[];reviews=[];signed.clear();await db.auth.signOut().catch(()=>{});throw e;}}
async function boot(){const callbackType=new URLSearchParams(location.hash.slice(1)).get('type');const needsSetup=['invite','magiclink','recovery'].includes(callbackType)||cleanHash()==='/activate';if(live()&&window.supabase&&config.url&&config.key){db=window.supabase.createClient(config.url,config.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});if(live()){try{const session=checkResult(await db.auth.getSession());user=session.session?.user||null;if(user){await loadProfile();if(needsSetup){authMode='setup';history.replaceState(null,'','#/auth');}}else if(needsSetup){authMessage='链接已失效，请重新获取开通或密码重设邮件。';history.replaceState(null,'','#/auth');}}catch(e){authMessage=friendly(e);history.replaceState(null,'','#/auth');notify(friendly(e));}}}if(cleanHash()==='/tongue-demo'||cleanHash()==='/followup-demo'){const section=cleanHash();demo=true;teacherDemo=false;seedDemo();go(section==='/tongue-demo'?'/case/demo-1/compare':'/due');return;}if(cleanHash()==='/demo'){beginDemo(false);return;}if(cleanHash()==='/teacher-demo'){beginDemo(true);return;}await render();}
boot();
